<script lang="ts">
 import {tick} from 'svelte';
 import {fleetLocation,fleetPowerPreview} from './fleet-preview';
 import type {PlayerState,PublicSetup} from './setup';
 let {game,player}:{game:PublicSetup;player:PlayerState}=$props();
 let reader=$state<HTMLDialogElement>(undefined!),opener=$state<HTMLButtonElement>(undefined!);
 let turned=$state(false),view=$state<'ships'|'power'|'rules'>('ships'),shipIndex=$state(0),locationIndex=$state(0);
 let selected=$state(''),sideways=$state(false),angled=$state(false);
 const groups=$derived([...new Set(player.ships.map(s=>s.location))].map(location=>({...fleetPowerPreview(game,player.position,location,player.ships),ships:player.ships.map((s,index)=>({...s,number:index+1})).filter(s=>s.location===location)})));
 const ship=$derived(player.ships.find(s=>s.id===selected));
 const currentShip=$derived(player.ships[Math.min(shipIndex,player.ships.length-1)]);
 const currentGroup=$derived(groups[Math.min(locationIndex,groups.length-1)]);
 async function open(){view='ships';shipIndex=0;locationIndex=0;selected='';const angle=parseFloat(getComputedStyle(opener).getPropertyValue('--reader-angle'))||0;reader.style.setProperty('--reader-angle',String(angle)+'deg');turned=angle%360!==0;sideways=angle%180!==0;angled=angle%90!==0;await tick();reader.showModal();}
 function portal(host:HTMLDivElement){const node=host.querySelector('dialog')!;document.body.append(node);return{destroy:()=>node.remove()};}
 function trap(event:KeyboardEvent){if(event.key!=='Tab')return;event.stopPropagation();const controls=[...reader.querySelectorAll<HTMLElement>('button,[tabindex="0"]')];if(event.shiftKey&&document.activeElement===controls[0]){event.preventDefault();controls.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===controls.at(-1)){event.preventDefault();controls[0]?.focus();}}
</script>
<button class="fleet-opener" bind:this={opener} aria-label={`Inspect ${player.name} fleet`} aria-haspopup="dialog" onclick={open}>Fleet ↗</button>
<div use:portal style="display:contents">
 <dialog data-e2e-layout class="fleet-reader" class:sideways class:angled class:turned bind:this={reader} aria-label="Fleet inspection" onkeydown={trap} onclose={()=>opener?.focus({preventScroll:true})}>
  <header><div><p>PUBLIC FLEET REGISTER</p><h2>{player.name} · fleet</h2></div><button onclick={()=>reader.close()} aria-label="Close fleet inspection">Close ×</button></header>
  <div class="fleet-total"><strong>{player.ships.length} ships</strong><span>{player.ships.reduce((n,s)=>n+s.level,0)} total power across all locations</span><small>Control is compared separately at each location.</small></div>
  {#if turned}<nav class="fleet-tabs" aria-label="Fleet inspection views">{#each ['ships','power','rules'] as tab}<button aria-pressed={view===tab} onclick={()=>view=tab as typeof view}>{tab==='ships'?'Ships':tab==='power'?'Location power':'Rules'}</button>{/each}</nav>{/if}
  <!-- svelte-ignore a11y_no_noninteractive_tabindex (Named bounded inventory supports keyboard scrolling.) -->
  <div class="fleet-body" role="region" aria-label="Ships and location power" tabindex="0">
   {#if turned}
    {#if view==='ships'}
     {#if currentShip}<nav class="page-controls" aria-label="Fleet ship register"><button aria-label="Previous fleet ship" onclick={()=>shipIndex=(shipIndex+player.ships.length-1)%player.ships.length}>‹</button><span>Ship {shipIndex+1} / {player.ships.length}</span><button aria-label="Next fleet ship" onclick={()=>shipIndex=(shipIndex+1)%player.ships.length}>›</button></nav><article class="current-cube" aria-label="Selected ship details"><span class="cube" aria-hidden="true">{currentShip.level}</span><div><h3>Ship {shipIndex+1} · level {currentShip.level}</h3><p>{fleetLocation(game,currentShip.location)}</p><small>{currentShip.level===4?'Maximum level':'Owned resource cube'} · {currentShip.level} power here</small></div></article>{:else}<p>No ships are on the map. Their cubes remain in other parts of your economy.</p>{/if}
    {:else if view==='power'}
     {#if currentGroup}<nav class="page-controls" aria-label="Fleet location register"><button aria-label="Previous fleet location" onclick={()=>locationIndex=(locationIndex+groups.length-1)%groups.length}>‹</button><span>{currentGroup.title}<small>Location {locationIndex+1} / {groups.length}</small></span><button aria-label="Next fleet location" onclick={()=>locationIndex=(locationIndex+1)%groups.length}>›</button></nav><dl aria-label={`${currentGroup.title} public fleet power`}>{#each currentGroup.powers as row}<div><dt>{row.name}</dt><dd>{row.before} power</dd></div>{/each}</dl><p class="control">{currentGroup.controllable?`Current outpost: ${game.players.find(p=>p.position===currentGroup.beforeOwner)?.name??'uncontrolled'}.`:'This location cannot be controlled.'}</p>{:else}<p>No locations have an owned ship.</p>{/if}
    {:else}<p class="reference">Ship levels range from 1 to 4. Fleet power is their summed levels at a location. A tied incoming fleet does not displace an incumbent. Inspection spends nothing and moves no ships.</p>{/if}
   {:else}
   {#if ship}<div class="selected-ship" aria-live="polite"><strong>Ship {player.ships.findIndex(s=>s.id===ship.id)+1} · level {ship.level}{ship.level===4?' · maximum level':''}</strong><span>{fleetLocation(game,ship.location)} · this ship contributes {ship.level} power here</span><small>Inspection spends nothing and moves no ships.</small></div>{/if}
   {#each groups as group}<section aria-label={`${group.title} fleet inventory`}><h3>{group.title}</h3><p class="location-power"><strong>{group.powers.find(p=>p.position===player.position)?.before} power</strong> · {group.ships.length} owned ship{group.ships.length===1?'':'s'}</p><div class="ship-list">{#each group.ships as s}<button aria-pressed={selected===s.id} aria-label={`Inspect ship ${s.number} · level ${s.level} at ${group.title}`} onclick={()=>selected=s.id}><span class="cube" aria-hidden="true">{s.level}</span><span><strong>Ship {s.number} · level {s.level}</strong><small>{s.level===4?'Maximum level':'Owned resource cube'}</small></span></button>{/each}</div><dl>{#each group.powers.filter(p=>p.before>0) as row}<div><dt>{row.name}</dt><dd>{row.before} power</dd></div>{/each}</dl><p class="control">{group.controllable?`Current outpost: ${game.players.find(p=>p.position===group.beforeOwner)?.name??'uncontrolled'}.`:'This location cannot be controlled.'}</p></section>{:else}<p>No ships are on the map. Your cubes remain in other parts of your economy.</p>{/each}
   <p class="reference">Ship levels range from 1 to 4. Fleet power is their summed levels at a location. A tied incoming fleet does not displace an incumbent.</p>
   {/if}
  </div>
 </dialog>
</div>
<style>
.fleet-opener{flex:none;min-height:44px;min-width:72px;padding:8px 12px;border:1px solid #ad925d;border-radius:6px;background:linear-gradient(#f2e6c9,#d4bd8d);color:#293c35;font:600 14px 'Atkinson Hyperlegible',sans-serif;cursor:pointer}.fleet-reader{transform:rotate(var(--reader-angle,0deg));width:min(850px,94vw);max-height:90dvh;padding:0;border:2px solid #a98c53;border-radius:14px;background:linear-gradient(130deg,#f4e9d1,#d5c29c);color:#283b33;box-shadow:0 20px 80px #000c,inset 0 0 0 5px #fff4;font:16px/1.4 'Atkinson Hyperlegible',sans-serif}.fleet-reader[open]{display:grid;grid-template-rows:auto auto minmax(0,1fr);grid-template-columns:minmax(0,1fr)}.fleet-reader>*{min-width:0}.fleet-reader::backdrop{background:#071015dc}.fleet-reader header{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:16px 20px;border-bottom:1px solid #967c4c;background:#eee0bf}.fleet-reader header p{font-size:11px;letter-spacing:.12em;margin:0}.fleet-reader h2{font:600 31px 'Cormorant Garamond',serif;margin:0;overflow-wrap:anywhere}.fleet-reader header button{flex:none;min-height:44px;min-width:80px;background:#2a413b;color:#f8ebc9;border:1px solid #8e764b;border-radius:6px;padding:8px;font:inherit;cursor:pointer}.fleet-total{padding:12px 20px;border-bottom:1px solid #927b4f66;display:flex;align-items:baseline;flex-wrap:wrap;gap:4px 14px}.fleet-total>strong{font:600 28px 'Cormorant Garamond',serif}.fleet-total>span{font-size:14px}.fleet-total small{flex-basis:100%;font-size:12px}.fleet-body{min-height:0;overflow:auto;padding:18px 20px;scrollbar-color:#8b7446 #e6d6b6}.fleet-body>section{border:1px solid #a58a55;border-radius:8px;padding:14px;background:#fff4;margin-bottom:14px}.fleet-body h3{font:600 28px 'Cormorant Garamond',serif;margin:0}.location-power{font-size:14px;margin:5px 0 12px}.ship-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px}.ship-list button{min-height:64px;display:flex;gap:12px;align-items:center;padding:10px;border:1px solid #8c784f;border-radius:7px;background:linear-gradient(130deg,#2c4944,#19343a);color:#f4e6c4;text-align:left;cursor:pointer;font:14px 'Atkinson Hyperlegible',sans-serif}.ship-list button[aria-pressed="true"]{outline:2px solid #237e75;outline-offset:1px;background:#27635a}.ship-list strong,.ship-list small{display:block}.ship-list small{margin-top:5px;color:#dad2b9;font-size:12px}.cube{display:grid;place-items:center;flex:none;width:44px;height:44px;border:1px solid #7ed8cf;border-radius:7px;background:linear-gradient(130deg,#52b8b0,#1f6e6b);box-shadow:inset -5px -5px #103d4566,inset 3px 3px #b6f4df44,2px 4px #14383e;color:#fff4cb;font:600 30px 'Cormorant Garamond',serif}dl{margin:12px 0 0;display:grid;gap:4px}dl div{display:flex;justify-content:space-between;gap:16px;font-size:13px}dd{margin:0;font-weight:700}.control{font-size:12px;margin:10px 0 0}.selected-ship{padding:13px;border:1px solid #8f794c;border-radius:7px;background:#e5d6b3;margin-bottom:14px}.selected-ship strong,.selected-ship span,.selected-ship small{display:block}.selected-ship span{font-size:14px;margin-top:4px}.selected-ship small{font-size:12px;margin-top:6px}.reference{font-size:13px;line-height:1.4;margin:12px 0 0}button:focus-visible,.fleet-body:focus-visible{outline:3px solid #237f75;outline-offset:3px}.fleet-reader.sideways{width:min(850px,80vmin);max-height:68vmin}.fleet-reader.angled{width:min(850px,68vmin);max-height:64vmin}@media(max-width:600px){.fleet-reader header,.fleet-body{padding:12px 14px}.fleet-reader h2{font-size:26px}.fleet-total{padding:10px 14px}.ship-list{grid-template-columns:1fr}}@media(min-width:2200px){.fleet-reader{width:1150px;font-size:24px}.fleet-reader.sideways{width:min(1150px,80vmin)}.fleet-reader.angled{width:min(1150px,68vmin)}.fleet-reader header{padding:24px 30px}.fleet-reader h2{font-size:44px}.fleet-reader header p{font-size:16px}.fleet-reader header button{min-height:60px}.fleet-body{padding:24px 30px}.fleet-total{padding:18px 30px}.fleet-total>strong{font-size:40px}.fleet-total>span{font-size:22px}.fleet-total small{font-size:18px}.fleet-body h3{font-size:38px}.ship-list{grid-template-columns:repeat(auto-fit,minmax(290px,1fr))}.ship-list button{font-size:22px;min-height:80px}.ship-list small{font-size:18px}.cube{width:62px;height:62px;font-size:42px}.location-power,.selected-ship span{font-size:22px}.selected-ship small,dl div,.control,.reference{font-size:18px}}

.fleet-reader.turned{height:min(800px,64vmin)}.fleet-reader.turned[open]{grid-template-rows:auto auto auto minmax(0,1fr)}.fleet-tabs{display:flex;gap:7px;padding:8px 14px;border-bottom:1px solid #927b4f66}.fleet-tabs button{flex:1;min-height:44px;border:1px solid #8c784f;border-radius:6px;background:#e6d7b4;color:#283b33;font:14px 'Atkinson Hyperlegible',sans-serif;padding:7px}.fleet-tabs button[aria-pressed=true]{background:#284d48;color:#f3e6c4}.turned .fleet-body{padding:10px 14px}.page-controls{display:grid;grid-template-columns:44px minmax(0,1fr) 44px;align-items:center;gap:8px;margin:0 0 8px}.page-controls>span{text-align:center;font-size:14px}.page-controls small{display:block;font-size:11px}.page-controls button{width:44px;height:44px;border:1px solid #8c784f;border-radius:6px;background:#25473f;color:#f3e6c4;font-size:25px;padding:0}.current-cube{display:flex;gap:14px;align-items:center;padding:10px 12px;border:1px solid #a58a55;border-radius:7px;background:#fff4}.current-cube h3{font-size:24px}.current-cube p{font-size:14px;margin:4px 0}.current-cube small{font-size:12px}.turned .reference{margin:0;font-size:14px;line-height:1.5}.turned dl{margin:0}.turned .control{margin:8px 0 0}@media(min-width:2200px){.fleet-tabs{padding:12px 24px;gap:12px}.fleet-tabs button{font-size:22px;min-height:60px}.turned .fleet-body{padding:20px 24px}.page-controls{grid-template-columns:60px minmax(0,1fr) 60px;gap:16px;margin-bottom:16px}.page-controls button{width:60px;height:60px;font-size:35px}.page-controls>span{font-size:25px}.page-controls small{font-size:18px}.current-cube{padding:20px;gap:24px}.current-cube h3{font-size:38px}.current-cube p{font-size:24px}.current-cube small,.turned .reference{font-size:20px}}
</style>
